// Traducción de data/recorrido.js (generado desde _docs/guion-demo.md): { huella del texto en español: texto }.
// Pendientes: make i18n-estado IDIOMA=de
I18N.registrarDatos('de', {
  "19871762": "Bevor wir ins Detail gehen, ein wichtiger Punkt. Was wir Ihnen zeigen, ist ein Beispiel für die Erfahrung von Logicalis bei der Einführung von Lösungen für KI-Governance und -Observability bei Kunden aus verschiedenen Branchen.",
  "28036771": "Integrität des Protokolls → Manipulation simulieren: Die Kette bricht und das Thermometer wird rot. Rückgängig machen.",
  "51833419": "Menschliches Eingreifen: MSG-A-04",
  "60808962": "KPIs: 19 offene Maßnahmen (2 kritisch), erzielte Ersparnis 0 €/Monat von möglichen 278 €, 9 regulatorische Risiken, 4 zu bereinigende Wissensdatenbanken. Der Kreis des Thermometers oben rechts.",
  "66349320": "Die ersten vier sind die KI-Agenten, die in einer Kette arbeiten: Mehrkanal-Eingang, der die Meldung über jeden Kanal empfängt und in ein einziges Format bringt; Spartenzuordnung; Datenextraktion; und die Anwendung der Geschäftsregeln für Kfz, Hausrat und Gesundheit.",
  "70314474": "Der Bereich Betrug bewertet jede Meldung anhand der Betrugsmuster, die die Gesellschaft bereits erkannt hat, und schickt die riskantesten Fälle an die Sonderermittlungseinheit.",
  "75980032": "Konfigurierte Caps → auf CAP-03 klicken: die Karte mit den beteiligten Agenten und dem Verlauf der Überschreitungen. Neues Cap (optional, ohne Speichern schließen).",
  "80623541": "Die Kennzahlen oben geben uns die effektive Autonomie, also wie viele Entscheidungen ohne menschliches Eingreifen durchlaufen; wie viele die Sachbearbeiter korrigieren; wie viel wir gegenüber dem Cap ausgegeben haben; und welche Warnungen offen sind, ob zu Kosten, Betrug, Wissen oder Compliance.",
  "91191363": "Wohin das Geld geht und warum: Bei Regeln macht die Ausgabe von gpt-5 63 % seiner Kosten aus. Schaltfläche € / %.",
  "306004a8": "Das Problem: FNOL und KI-Governance",
  "4700a85e": "Einführung · Das Problem",
  "794f53d9": "Die erste Meldung entscheidet viel über den weiteren Verlauf des Schadens, und die KI, die sie automatisiert, muss unter Kontrolle sein.",
  "ad4a444b": "Bevor wir anfangen, möchte ich klären, worüber wir sprechen. In Spanien werden laut UNESPA jedes Jahr rund 11 Millionen Kfz-Schäden gemeldet; das ist einer alle drei Sekunden.",
  "a0a16a4f": "Und alle beginnen gleich: mit einer ersten Meldung des Kunden.",
  "428f9813": "Diese Meldung erreicht uns über fünf Kanäle gleichzeitig. Es kann eine lange E-Mail mit Anhängen sein, ein Webformular, ein Chat, ein Anruf, den jemand transkribieren muss, oder eine WhatsApp, in Eile geschrieben und voller Emojis.",
  "2df50db2": "Und ab diesem Moment läuft die Uhr, denn das spanische Versicherungsvertragsgesetz gibt in Artikel 16 sieben Tage für die Schadenmeldung.",
  "33d9549f": "Bei FNOL entscheidet sich viel von dem, was danach passiert. Wird die Sparte falsch zugeordnet, wandert die Akte zwischen den Teams hin und her. Fehlt eine Angabe, muss jemand den Kunden zurückrufen.",
  "ac1e6fce": "Rutscht uns hier ein Betrugshinweis durch, ist er später viel schwerer zu finden. Und es ist auch der erste Kontakt des Kunden mit seinem Versicherer, meist an einem schlechten Tag.",
  "da04e715": "Heute erledigt diese ganze Arbeit ein Mensch: Er liest die Meldung, ordnet sie zu und tippt die Daten ins System.",
  "2d8bb0f4": "Damit Sie eine Vorstellung vom Gewicht bekommen: In den Vereinigten Staaten macht die Schadenbearbeitung rund 10 % der Kfz-Prämie aus. Dorthin gehen unsere Zeit und unser Geld.",
  "d9241ffe": "Und es gibt ein zweites Problem.",
  "f9c17601": "Sobald wir KI in einen solchen Prozess bringen, müssen wir sie aus vielen Blickwinkeln kontrollieren: wie viel Autonomie wir den Agenten geben, ob die Wissensdatenbanken, die sie nutzen, gesund sind, ob wir die Vorschriften einhalten und was uns jede Entscheidung kostet.",
  "bc0786b3": "Eine Meldung mit KI zuzuordnen, hebt niemanden mehr ab; mit einem guten Prompt erreicht man über 90 % Genauigkeit. Die eigentliche Herausforderung ist der Schritt vom Piloten in die Produktion.",
  "4d7f2089": "Gartner schätzt, dass mehr als 40 % der Projekte mit agentischer KI vor Ende 2027 eingestellt werden, wegen der Kosten, eines unklaren Nutzens oder unkontrollierter Risiken. Das heißt: Projekte scheitern nicht, weil die KI versagt.",
  "ffc1643e": "Sie scheitern, weil niemand drei Fragen beantworten kann: warum sie so entschieden hat, wer sie kontrolliert und was sie kostet.",
  "c53d5454": "Die Lösung: eine integrierte, gesteuerte Plattform",
  "640eab80": "Einführung · Die Lösung, Block für Block von oben nach unten",
  "c813c4f8": "Wir automatisieren den ersten Kontakt, mit der KI unter Kontrolle.",
  "f4d8d573": "Woher diese Plattform kommt",
  "0e150700": "Wir haben in einem einzigen Fall vieles zusammengeführt, was wir in verschiedenen Projekten umgesetzt haben.",
  "76b5ab98": "Die Branche ändert sich, das Ziel bleibt immer dasselbe: Kontrolle haben, um bessere Ergebnisse zu erzielen, den Kunden besser zu bedienen, die Ausgaben zu steuern und die Vorschriften einzuhalten.",
  "1dc2142c": "Heute sehen wir es angewandt auf die erste Schadenmeldung.",
  "53148d6d": "Was sie tut",
  "4095d25a": "Was wir Ihnen heute zeigen, ist eine integrierte Plattform, die diesen ersten Kontakt automatisiert.",
  "d95e437f": "Wir haben vier KI-Agenten, die die Meldung über jeden Kanal empfangen, entscheiden, zu welcher Sparte sie gehört, die Daten extrahieren und die Geschäftsregeln des Versicherers anwenden.",
  "2c703e08": "Der Sachbearbeiter erhält die Meldung bereits zugeordnet, mit extrahierten Daten und einem Vorschlag: freigegeben oder zu prüfen.",
  "7cccca25": "Der Stapel, den wir verarbeiten, enthält 13 Meldungen. 10 werden selbstständig freigegeben und 3 gehen an einen Menschen, jede mit ihrem Grund und mit dem Satz des Kunden, der ihn belegt.",
  "27a3fd28": "Und so sieht das Governance-Panel in den letzten 14 Tagen aus: 16.720 verarbeitete Meldungen, 81 % effektive Autonomie, 19 % an einen Menschen eskaliert und nur 2,1 % der Entscheidungen von einem Sachbearbeiter korrigiert.",
  "e950c4e8": "Daneben die Kosten des Zeitraums, die aktiven Warnungen, die Compliance und der Zustand der Wissensdatenbanken.",
  "a7ccad14": "Die vier Agenten",
  "33ce67d1": "Die Idee ist, vier kleine Spezialisten zu haben statt einer einzigen KI, die alles macht. Jeder hat sein eigenes Modell, seine Prompt-Version, seinen Verantwortlichen und seine eigenen Caps.",
  "d33a93c3": "Und das teuerste Modell setzen wir nur dort ein, wo wirklich Reasoning nötig ist, also bei den Geschäftsregeln.",
  "0dd4606a": "Nachvollziehbarkeit",
  "dc5c366f": "Die Grundlage von allem ist die Nachvollziehbarkeit. Jede Entscheidung hinterlässt eine Spur: was hereinkam, was jeder Agent getan hat, mit welchem Modell, wie viele Tokens er verbraucht hat, was es gekostet hat und was er entschieden hat.",
  "5dbb3b4d": "Die KI-Anbieter bieten bereits technische Spuren an, und sie sind nötig, aber sie verstehen nicht, was eine Sparte, ein Selbstbehalt oder eine Frist von sieben Tagen ist.",
  "854bca3b": "Diese Lösung verbindet beide Welten, die technische Spur und den Geschäftsprozess des Versicherers, um jeder Gesellschaft eine passende Antwort zu geben.",
  "3991d1de": "Und auf dieser Spur bauen wir alles andere auf: Kontrolle von Autonomie und Ausgaben, Audit und Replay.",
  "03e9e665": "Autonomie und Reife der Agenten",
  "6602e207": "Jeder Agent hat eine Autonomiestufe, von L0, wo er nur vorschlägt, bis L3, wo er entscheidet und handelt. Diese Autonomie wird mit Daten verdient und mit Daten verloren.",
  "965d8824": "Als die Sachbearbeiter begannen, mehr als 3 % der Entscheidungen des Agenten Regeln zu korrigieren, fiel der Agent von L3 auf L2, mit Begründung und dem Namen dessen, der es genehmigt hat.",
  "cce98425": "Heute laufen 81 % der Entscheidungen ohne menschliches Eingreifen durch, und diesen Anteil unter Kontrolle zu halten, ist das, was es wirklich heißt, dass die Automatisierung funktioniert.",
  "7d55b08e": "Ausgaben unter Kontrolle",
  "c89fb053": "Wir steuern die Ausgaben sekundengenau und über Aktionen.",
  "5a68bd7c": "Die Anbieter von KI-Diensten für Unternehmen sagen Ihnen alle 8 Stunden, wie viel Sie ausgegeben haben, und in 8 Stunden kann viel passieren: Ein Agent in einer Schleife oder eine Spitze an Meldungen kann dazu führen, dass wir morgens mit Ausgaben aufwachen, die wir nicht wollten.",
  "e4a35a4c": "Hier addiert jede Entscheidung ihre Kosten in dem Moment, in dem sie entsteht, und jeder Agent hat seine Caps.",
  "93b79c6f": "Wird eines überschritten, handelt das System selbst: Es wechselt zum Beispiel auf ein günstigeres Modell und vermerkt das in jeder Spur, ohne den Dienst anzuhalten.",
  "a40124ac": "Betrug",
  "6219b823": "Beim Betrug kombiniert die Plattform, was die KI aus der Schilderung des Kunden versteht, mit der Historie von Policen und Schäden und mit deterministischen Regeln.",
  "9f5a6f92": "Damit erkennt sie die Betrugsmuster, die die Gesellschaft schon kennt: eine gerade abgeschlossene Police, ein Zahlungskonto, das sich bei verschiedenen Versicherungsnehmern wiederholt, oder ein Diebstahl ohne Anzeige.",
  "ea128514": "Und etwas Wichtiges: Der Indikator beschuldigt nicht, er priorisiert. Die Entscheidung trifft immer ein Mensch.",
  "3b5edfa9": "Nachweisbare Compliance",
  "8ac1d362": "Die DSGVO, DORA und die Stellungnahme der EIOPA zur KI gelten bereits. Der AI Act kommt später, und die Triage gilt nicht als Hochrisiko, aber wir wenden seine Artikel als gute Praxis an.",
  "00dee4d1": "Jede Entscheidung trägt ihren Compliance-Nachweis: welche personenbezogenen Daten es gab, warum so entschieden wurde und ob ein Mensch sie geprüft hat.",
  "b5914cb9": "Die Akteure: der Sachbearbeiter und wer die KI steuert",
  "7e69b680": "Einführung · Die Akteure",
  "fcf592e7": "Zwei Akteure, zwei Bildschirme: der Sachbearbeiter und wer die KI steuert.",
  "3b4263b8": "In der Demo sehen wir zwei Arten von Nutzern. Auf der einen Seite der FNOL-Sachbearbeiter, der auf dem Triage-Bildschirm arbeitet.",
  "02d85dd2": "Es ist eine sehr schnelle Oberfläche: Er sieht das Detail jeder Meldung, wie und warum sie zugeordnet wurde, warum die KI jede Entscheidung getroffen hat und die Betrugshinweise, mit dem Satz des Kunden, der sie belegt.",
  "acc81f98": "So verwendet er seine Zeit auf die Fälle, die Urteilsvermögen brauchen.",
  "ed462c25": "Auf der anderen Seite die Teams, die die KI steuern: IT, Finanzen, Compliance, Risiko, Audit oder der DSB, die im Governance-Panel arbeiten.",
  "82384c5c": "Von dort sehen sie, ob die Agenten gut entscheiden, mit welchem Wissen, was sie kosten und ob der Versicherer nachweisen kann, dass er die Vorschriften einhält.",
  "29ff22c9": "Die Demo: ein Weg von Anfang bis Ende",
  "67ffe2bd": "Einführung · Die Demo",
  "a648deb2": "Wir begleiten eine Meldung von Anfang bis Ende und sehen alles, was die KI hinterlässt.",
  "9c201759": "Die Demo ist ein Weg. Er beginnt mit dem Eingang einer Meldung, geht weiter mit ihrer Analyse durch die Agenten und der Prüfung durch den Sachbearbeiter und führt über die Belege, die die KI zu jeder Entscheidung hinterlässt.",
  "65ee7ee2": "Und er endet im Governance-Panel, wo wir verstehen werden, welche Agenten beteiligt waren, was sie wie getan haben, welche Caps sie hatten, welches Reasoning dahintersteht, welches Wissen sie genutzt haben, wie konform die Lösung ist, wann sie Geld ausgibt und warum, und wie wir all das verbessern können.",
  "fbba8b17": "Übergang zur Demo",
  "e6e45db5": "Schauen wir es uns an. Zuerst zeige ich Ihnen, was der Sachbearbeiter sieht, und dann, was diejenigen sehen, die die KI steuern: der Verantwortliche der Agenten, der Auditor und der CFO.",
  "f8f32821": "Die sechs Phasen und die fünf Kanäle",
  "2c1a186e": "Triage, Leiste der nummerierten Phasen unter dem Kopfbereich",
  "c2ed24cd": "So funktioniert der Prozess von Anfang bis Ende.",
  "38f48b89": "Klick 1 · Mehrkanal: die aufklappende Karte mit den fünf Kanälen und ihrer Vereinheitlichung in ein einziges Format.",
  "2825eb3d": "Klick 2 · Spartenzuordnung, 3 · Datenextraktion und 4 · Geschäftsregeln: auf jeder Karte unten das Etikett «Generative KI» oder «Geschäftslogik».",
  "54abe1de": "Klick 5 · Nachvollziehbarkeit und 6 · Automatisierung.",
  "167d2812": "Seitenmenü → Meldungspaket: die Liste der 13 mit dem Symbol ihres Kanals. Auf MSG-A-11 (WhatsApp) und MSG-A-08 (Telefon) hinweisen.",
  "963e8dae": "Hier sehen Sie die sechs Phasen des Prozesses.",
  "35f3dd06": "Die letzten beiden, Nachvollziehbarkeit und Automatisierung, schließen den Kreis: Sie protokollieren alles, was passiert, und machen aus der Entscheidung einen Arbeitsablauf.",
  "6e60d333": "Jede Phase hat ihre Karte, die erklärt, was sie empfängt, was sie liefert und ob ein KI-Modell oder eine Geschäftsregel sie übernimmt.",
  "6cf0c577": "Für den Versicherer bedeutet das, dass eine Meldung per WhatsApp genau nach denselben Kriterien behandelt wird wie eine per E-Mail. Der Kunde wählt den Kanal, der ihm am besten passt, und die Gesellschaft verliert keine Nachvollziehbarkeit.",
  "5c40de9f": "Beim Sachbearbeiter kommt die Meldung bereits zugeordnet an, mit extrahierten Daten und einem Entscheidungsvorschlag, und er weiß, dass hinter jedem Agenten ein benannter Verantwortlicher steht.",
  "b2b6563e": "Außerdem sind diese Karten genau die Dokumentation, die ein Auditor verlangt, bevor er ein KI-System abnimmt.",
  "9ec08663": "Verarbeitung von Paket A",
  "17fe7768": "Triage, Hauptbereich",
  "774fbb39": "In Sekunden wissen wir, was freigegeben ist und was ein Mensch prüfen muss.",
  "4af90e90": "Paket verarbeiten. Während es läuft, auf die Zähler (Freigegeben, Zu prüfen, Durchschnittliche Zykluszeit) und das sich füllende Protokoll hinweisen.",
  "b0854b68": "In der Mitte des Stapels Pausieren. Erklären, dass nichts verloren geht. Fortsetzen.",
  "6982deb1": "Am Ende: 10 freigegeben und 3 zu prüfen. Auf die Chips nach Sparte hinweisen.",
  "127f490d": "Spalte Sparte: das ✔ gegenüber dem erwarteten Ergebnis. Spalten Herkunft und Konf.",
  "d542152d": "Filter Nur zu prüfen: Es bleiben MSG-A-04, MSG-A-08 und MSG-A-13. Den Filter entfernen.",
  "012d46db": "Auf die Betrugsetiketten im Protokoll hinweisen (MSG-A-13 mit der SIU; MSG-A-09, MSG-A-11 und MSG-A-02 mit zurückgehaltener Zahlung).",
  "01aa5651": "Optional: JSON exportieren.",
  "0e6be969": "Bei der Verarbeitung des Pakets durchläuft jede Meldung die vier Agenten und kommt mit ihrer Sparte, ihren Daten und ihrer Entscheidung heraus.",
  "3aa11ea1": "Die Zähler für Freigegebene, zu prüfende Fälle und durchschnittliche Zeit aktualisieren sich live, und der Stapel lässt sich jederzeit anhalten, ohne dass etwas verloren geht.",
  "4184afb8": "Gleichzeitig hinterlässt jede Meldung sofort ihre Spur: das Modell, das jeder Agent genutzt hat, die Tokens, die Kosten in Euro und die Entscheidung.",
  "04163b43": "So kann der Sachbearbeiter seine Zeit auf die Fälle verwenden, die wirklich Urteilsvermögen brauchen, statt die anderen abzutippen. In den letzten 14 Tagen liefen 81 % der Entscheidungen ohne menschliches Eingreifen durch.",
  "308dc710": "Und das Protokoll entsteht von selbst, ohne Handarbeit. Es ist der Nachweis, den der Versicherer in einem Audit vorlegt.",
  "8da409ce": "Die Akte einer freigegebenen Meldung: MSG-A-01",
  "bbf4ae0f": "Triage → Akte von MSG-A-01",
  "a98fe7c9": "Auch eine Freigabe muss erklärbar sein.",
  "e3bd2e65": "Oberer Teil der Akte: die drei Zahlen (Entscheidung, Sparte, Konfidenz 95 %) und die Schaltfläche Override auf der Karte Entscheidung. Darauf hinweisen, ohne zu bestätigen: Ein Override ändert die Zahlen im Governance-Panel.",
  "d869f154": "Reiter Meldung: die Belege im Text markiert und nummeriert. Mit der Maus über einen fahren: Der Titel «Beleg» wechselt zu seinem Typ (zum Beispiel «Schadendatum»). Legende öffnen.",
  "d2b07093": "Reiter Anhänge (3): der Unfallbericht im PDF-Viewer und rechts seine mit der E-Mail abgeglichenen Daten (alles stimmt; die Angaben zum anderen Fahrzeug stehen nur im Bericht). Zu den beiden Fotos wechseln: Auf das Bild klicken, um es zu vergrößern.",
  "54afea77": "Reiter Extrahierte Daten: die 10 Felder (Kunde, Police, Art, Datum, 1.350 €, Ort, Dritte ja, Verletzte nein, Unterlagen: Unfallbericht, Kostenvoranschlag und Fotos).",
  "e412d9e6": "Reiter Geschäftsregeln: A1 bis A8, alle «erfüllt» oder «nicht anwendbar», jede mit ihrem Beleg.",
  "67ce5bbf": "Reiter Begründung: Sparte, Entscheidung, empfohlener nächster Schritt und zeitlicher Ablauf.",
  "7c286492": "Das ist die Akte einer Entscheidung. Oben sehen wir die Entscheidung, die Sparte und die Konfidenz des Modells. Darunter die Meldung des Kunden mit den markierten Belegen.",
  "11bb9a21": "Jeder Beleg ist ein wörtliches Zitat aus der Meldung, und das System prüft, dass es im Originaltext steht: Erfindet das Modell ihn, erscheint er nicht.",
  "45ba8bba": "Diese Meldung kommt außerdem mit drei Anhängen: dem eingescannten Unfallbericht und zwei Fotos des Schadens. Im Reiter Anhänge sehen wir sie neben den Daten, die der Agent aus jedem gelesen hat, verglichen mit dem, was in der E-Mail steht.",
  "cbc54671": "Der Bericht bestätigt Datum, Uhrzeit und dass niemand verletzt wurde, und ergänzt Kennzeichen und Versicherer des anderen Fahrers, die nicht im Text standen.",
  "8afe0777": "Die Fotos zeigen leichte Schäden an Stoßstange und Scheinwerfer vorne rechts, genau das, was die Werkstatt veranschlagt hat.",
  "baf00b61": "In den nächsten Reitern sehen wir die Daten, die der Agent aus dem Freitext extrahiert hat, jede Regel der Sparte, die der Agent Regeln bewertet hat, mit Ergebnis und Beleg, und die Begründung, die ihn zur Entscheidung geführt hat.",
  "10525d64": "Einfache, gut dokumentierte Meldungen werden freigegeben, ohne dass jemand sie anfassen muss. Und wenn morgen jemand fragt, warum eine freigegeben wurde, steht die Antwort hier, Regel für Regel und mit den Worten des Kunden.",
  "f55005a6": "Der Sachbearbeiter muss keiner Blackbox vertrauen: Er kann jede Regel in Sekunden prüfen.",
  "b2f5922c": "Und er muss Bericht und Fotos nicht mehr öffnen, um sie von Hand mit der E-Mail zu vergleichen: Der Abgleich ist gemacht, und er muss nur auf das achten, was nicht übereinstimmt.",
  "5a9747f6": "Ist er mit einer Freigabe nicht einverstanden, schickt die Schaltfläche Override auf der Karte Entscheidung sie zur Prüfung, mit optionalem Kommentar.",
  "706d2a5b": "Diese Änderung zählt zur Override-Quote des Agenten, und diese Quote entscheidet über seine Autonomiestufe.",
  "bff729be": "Die Akte einer Meldung «Zu prüfen»: MSG-A-08",
  "43167b5f": "Triage → Akte von MSG-A-08. Volltext der Meldung in Schritt 1",
  "804234a9": "Jede Entscheidung ist erklärbar, auch wenn die Maschine nicht entscheidet.",
  "33a1adb7": "Reiter Meldung: markierte Belege («liegt im», «gebrochenem Schlüsselbein und zwei gebrochenen Rippen», «Protokoll», der Opel Astra des Dritten).",
  "da0fd0b3": "Reiter Geschäftsregeln: A5 · Dritte dokumentiert und keine Verletzten als «verletzt», mit seinem Beleg.",
  "47bcdf2e": "Reiter Extrahierte Daten: importe_estimado_eur leer. Darauf hinweisen.",
  "02bc50e4": "Reiter Begründung: warum es Kfz ist und nicht Gesundheit (die Ursache des Schadens ist der Verkehrsunfall).",
  "e6bd9a07": "Reiter Rohantwort → Ansicht An das Modell gesendet: die Platzhalter [PERSONA_1], [POLIZA_AU_1], [MATRICULA_1], [TELEFONO_1] statt der echten Daten. Der Bruch und der Diabetes stehen weiter da.",
  "be5b4e3a": "Karte Entscheidung: die Schaltfläche Bestätigen. Ein Klick lässt das Ergebnis wählen (Freigeben oder Auf «Zu prüfen» belassen) und einen Kommentar hinterlassen. Abbrechen, ohne zu bestätigen.",
  "2ad61ac4": "Geht eine Meldung zur Prüfung, sagt uns die Akte, welche Regel sie verletzt hat, und markiert die Sätze der Meldung, die das belegen.",
  "0f17bdb3": "Löst außerdem ein Guardrail aus, zum Beispiel weil jemand verletzt ist, kann der Agent nicht entscheiden, und der Fall geht direkt an einen Menschen.",
  "70d10509": "Steht eine Angabe nicht in der Meldung, bleibt das Feld leer. Der Agent hat die Anweisung, nichts zu erfinden.",
  "957371c9": "Und in der Rohantwort sehen wir genau, was das Modell erhalten hat.",
  "ff740ccd": "Bevor die Plattform ihm die Meldung schickt, ersetzt sie Namen, Policen, Kennzeichen, Telefonnummern und die übrigen personenbezogenen Daten durch Platzhalter.",
  "280f3559": "Was für die Entscheidung nötig ist, etwa die Verletzungen oder die Diagnose, bleibt erhalten.",
  "d8dbc552": "Wenn die Antwort zurückkommt, setzt die Plattform die echten Daten wieder in die Akte ein, und die Zuordnungstabelle existiert nur für die Dauer des Aufrufs im Speicher.",
  "e34ecdb9": "Der Sachbearbeiter versteht den Grund in Sekunden. Wenn er mit der Prüfung fertig ist, schließt er sie mit der Schaltfläche Bestätigen auf der Karte Entscheidung ab: Er wählt, ob er freigibt oder in der Prüfung belässt, und kann einen Kommentar hinterlassen.",
  "14559e08": "Da der Agent den Fall bereits eskaliert hatte, ist das kein Override und beeinflusst seine Autonomie nicht. Fragt der Kunde nach einer Erklärung, steht die Antwort schon in der Akte.",
  "54050dc1": "Und Personenschäden bewertet immer ein Mensch: In den letzten 14 Tagen erklärt der Guardrail für Verletzte 20 % der Eskalationen.",
  "be007f02": "Außerdem entscheidet das Modell, ohne zu wissen, wer der Versicherungsnehmer ist. Datenminimierung ist dann keine Richtlinie mehr, die in einem Dokument steht, sondern das, was das Modell tatsächlich erhält.",
  "25d71b97": "Die Rohantwort von MSG-A-12",
  "ebde2255": "Triage → Akte von MSG-A-12 → Reiter Rohantwort",
  "441a7aa7": "Das Modell zertifiziert sich nicht selbst: Die Plattform hinterlässt den Nachweis jeder Entscheidung.",
  "c9bd79ad": "Rohantwort mit eingeschaltetem + Governance: der Block _gobernanza, gekennzeichnet als «von der Plattform hinzugefügt, nicht vom Modell erzeugt».",
  "0f0dd49d": "Terrakottafarbener Block datos_personales: der Minderjährige (8 Jahre) und die Gesundheitsdaten in Rot, jeweils mit Kategorie und ob sie für die Entscheidung genutzt wurden.",
  "96d456fe": "Grüner Block explicabilidad: warum Gesundheit und warum weder Kfz noch Hausrat («\"Roller\" löst kein Kfz aus: Er ist kein versichertes Fahrzeug, und es gibt keinen Dritten»; «Hausrat verworfen: Der Sturz war im Park Valdebebas, nicht zu Hause»).",
  "837d02b4": "Blauer Block trazabilidad: Spur, Modell, Prompt-Version und verketteter SHA-256-Hash.",
  "7fd9fe8f": "Ockerfarbener Block retencion: 6 Monate für die Spur; 5 Jahre für die Akte des Personenschadens.",
  "b4c6376b": "Violetter Block supervision_humana. Mit der Maus über eine Vorschrift fahren, um zu sehen, was sie verlangt.",
  "c86d5a74": "Übergang: Kopfbereich → Agenten-Governance. Im Panel Quelle → Aktuelle Sitzung, damit die Spuren die des gerade verarbeiteten Stapels sind.",
  "b7a24bfc": "In der Rohantwort sehen wir, was das Modell zurückgegeben hat, und darunter einen Governance-Block, den die Plattform hinzufügt.",
  "4fdd852f": "Diesen Block erzeugt nicht das Modell: Die Plattform berechnet ihn mit festen Regeln, und er lässt sich jederzeit neu berechnen.",
  "7fef77e7": "Der Block hält fest, welche personenbezogenen Daten in der Meldung stehen, welcher Art sie sind, zum Beispiel Gesundheitsdaten oder Daten von Minderjährigen, und ob sie für die Entscheidung genutzt wurden. Er erklärt, warum die Meldung zu einer Sparte gehört und warum nicht zu den anderen beiden.",
  "15b78adc": "Und er fügt ein SHA-256-Siegel hinzu, das mit der vorherigen Entscheidung verkettet ist, zusammen mit der Dauer, für die die Spur aufbewahrt werden muss.",
  "bffa4e4c": "Gesundheitsdaten und Daten von Minderjährigen genießen verstärkten Schutz. Mit diesem Block sagt jede Antwort, welche sensiblen Daten es gab, wie sie behandelt wurden und ob sie für die Entscheidung genutzt wurden.",
  "641e281b": "Für den DSB ist das ein Nachweis Entscheidung für Entscheidung, keine allgemeine Erklärung.",
  "bda83532": "Und manipuliert jemand einen Datensatz, bricht die Hash-Kette und das fällt sofort auf. Wir prüfen es gleich im Panel.",
  "67744a95": "Eintritt in das Governance-Panel",
  "e870489f": "Governance-Panel → Start. Die sechs Blöcke von oben nach unten durchgehen, ohne einen davon zu öffnen",
  "b7606025": "Sechs Fragen, um unsere Agenten zu steuern.",
  "8df97bd4": "Jetzt wechseln wir zum Panel derjenigen, die die Agenten steuern.",
  "5d81cd3a": "Es ist in dreizehn Bereiche gegliedert, die sechs Fragen beantworten: was passiert, wie viel die Maschine entscheidet und wie viel ein Mensch, ob es Betrugshinweise gibt, ob die Agenten gut und mit gutem Wissen entscheiden, ob wir die Vorschriften einhalten und was es uns kostet, und was wir korrigieren müssen.",
  "ed889cef": "Jede Karte dieser Startseite gibt uns die Zahl des Tages und ihren Status. Wir gehen in jeden Bereich mit den Meldungen des gerade verarbeiteten Stapels.",
  "fc660dec": "Übersicht",
  "535a2bd1": "Start → Übersicht ansehen. Block Betrieb",
  "789ad0ff": "Volle Kontrolle über das System und die Möglichkeit, es sofort anzuhalten.",
  "f282c8fc": "Die 8 KPIs: 16.720 Meldungen in 14 Tagen, effektive Autonomie 81 %, eskaliert 19 %, Overrides 2,1 %, Kosten des Zeitraums, 11 Warnungen, Compliance 87 % und 5 von 9 gesunden Wissensdatenbanken.",
  "482664b5": "Auf den KPI Aktive Warnungen klicken: das Fenster mit den 11 Warnungen nach Schweregrad und nach Herkunft (Kosten 3, Betrug 3, Wissensdatenbanken 3, Compliance 2) und die nach Herkunft gruppierte Liste. In der Gruppe Betrug: MSG-A-13 an die SIU eskaliert (Klick: öffnet die Fallkarte), die 3 zurückgehaltenen Zahlungen über 2.080 € und CAP-09 in Warnung. Schließen.",
  "a3f4c211": "Die Karten der vier Agenten: Regeln Herabgestuft (gpt-5-mini) und 13,70 € gegenüber einem Tages-Cap von 12 €.",
  "0c6962d4": "Diagramm Tageskosten gegenüber dem Cap: Schaltfläche Vergrößern (Fenster mit dem Detail pro Tag).",
  "1195a47b": "Die aktiven Warnungen der Karte, nach Schweregrad sortiert: die von CAP-03, die von MSG-A-13 mit der SIU und die von KB-06 (Werkstattnetzwerk).",
  "e251476c": "Letzte Spuren → auf die von MSG-A-08 klicken: die erklärte Karte (was hereinkam, was jeder Agent getan hat, Entscheidung, Kosten). Schaltfläche Compliance in der Karte. Schließen.",
  "c9bc9ccf": "Kill Switch von Datenextraktion: Die Karte wird dunkel. Wieder einschalten.",
  "35bf525d": "Die Übersicht zeigt uns auf einem einzigen Bildschirm die Kennzahlen des Zeitraums, den Status jedes Agenten, die Kosten gegenüber dem Budget und die Warnungen aus allen Quellen.",
  "e77067b7": "Wir wollen, dass die Geschäftsleitung in zehn Sekunden weiß, ob das System gut läuft, ohne jemanden um einen Bericht bitten zu müssen.",
  "1a3efb02": "Öffnen wir die Kennzahl der Warnungen, sehen wir sie nach Herkunft sortiert, jede mit einem Link zu ihrem Bereich.",
  "db3b4888": "Darunter hat jeder Agent seine Karte mit Status, Modell, Latenz und dem, was er heute gegenüber seinem Budget ausgegeben hat. Und jede Karte hat einen Stoppschalter, den Kill Switch, der den Agenten mit einem Klick anhält.",
  "f283cf47": "Im Moment haben wir 81 % Autonomie und 2,1 % korrigierte Entscheidungen, unter dem Ziel von 3 %.",
  "0f57327a": "Und wenn sich ein Agent schlecht verhält, halten wir ihn sofort an. Seine Meldungen bleiben in der Warteschlange, bis wir ihn wieder starten, keine geht verloren, und der Stopp wird mit dem Namen dessen protokolliert, der ihn ausgelöst hat.",
  "bbaeab14": "Agenten: der Agent Regeln",
  "4782d17a": "Menü → Agenten → Reiter Geschäftsregeln. Block Betrieb",
  "b5708174": "Jeder Agent hat seine Identität, seinen Verantwortlichen und nur die Berechtigungen, die er braucht.",
  "001bb471": "Die Kette oben: Mehrkanal → Klassifizierung → Extraktion → Regeln, mit dem, was sie weitergeben (normalisierter Text → Sparte und Signale → 10 Felder).",
  "6baf585f": "Kopf von Regeln: Herabgestuft, L2, Verantwortlicher «Schadenmanagement · KI-Ausschuss», gpt-5, Prompt v2.3, Latenz p50/p95, 13,70 € / 12 €.",
  "0b1aec68": "Identität und Berechtigungen: Er darf die Police lesend abfragen und Vorschläge machen; er darf keine Zahlungen anordnen, keinen Schaden ablehnen und die Akte nicht ändern.",
  "a9eec172": "Konfiguration und Variablen: Mindestkonfidenz 0,85, Höchstbeträge, Reasoning-Aufwand «medium», Override-Ziel 3 %.",
  "f0f80d06": "Leistung und Kosten: 172,65 € in 14 Tagen; die Tabelle Verhalten je nach Modell (gpt-5 mit 98,9 % Genauigkeit für 0,011 € pro Meldung; herabgestuftes gpt-5-mini mit 97,6 % für 0,002 €).",
  "ee9ddff1": "Qualität: der Kreis mit 98 %, Genauigkeit 13/13, durchschnittliche Konfidenz 0,93, 9,77 verifizierte Belege pro Entscheidung.",
  "9f8520de": "Genutzte Knowledge Bases: KB-02 beeinträchtigt und KB-06 kritisch (wir sehen sie in Schritt 14).",
  "69ea25f6": "Optional für technische Profile: Ein- und Ausgabevertrag mit dem echten Beispiel.",
  "e52a7c9e": "Der Bereich Agenten gibt uns den vollständigen Steckbrief jedes Agenten: was er tut, welches Modell er nutzt, wie viele Tokens er verbraucht, wie lange er braucht, was er kostet, wie er je nach Modell abschneidet und welches Wissen er abfragt.",
  "b615367f": "Die Agenten unter Kontrolle zu halten, ist entscheidend, denn sie sind unsere autonomen Mitarbeiter.",
  "c22d782e": "Wir müssen wissen, welche Probleme sie haben, um ihnen zu helfen, mit welchem Wissen sie arbeiten, um es aktuell zu halten, und ob sie rentabel sind, um mit Daten zu entscheiden und kein Geld zu verlieren.",
  "bedc17d9": "Jeder Agent hat eine eigene Identität, wie ein Mitarbeiter, mit einem Verantwortlichen und minimalen Berechtigungen: Es ist festgelegt, was er darf und was nicht.",
  "01736076": "Im Steckbrief sehen wir seine Konfiguration und Schwellen, die Guardrails und Caps, die ihn begrenzen, seine Kosten und Tokens der letzten Tage und eine Tabelle mit seinem Verhalten je nach genutztem Modell: Genauigkeit, Eskalationen, Korrekturen, Kosten pro Meldung und Latenz.",
  "d601744d": "Wir sehen auch einen Qualitätsindex, die Wissensdatenbanken, die er nutzt, und für die technischeren Profile seinen Ein- und Ausgabevertrag.",
  "df2c81ac": "Mit diesem Steckbrief entscheiden wir mit Zahlen, welches Modell in jedem Agenten zum Einsatz kommt. Heute verursacht zum Beispiel der Agent Regeln 80 % der Ausgaben und hat zwei Wissensdatenbanken mit Problemen. Dort müssen wir ansetzen.",
  "9752db10": "Menü → Nachvollziehbarkeit. Block Betrieb",
  "e7f5c0be": "Meldung für Meldung: was passiert ist, wer es entschieden hat und was es gekostet hat.",
  "b0efbeb3": "Auf die Spur von MSG-A-08 klicken: Das feste Panel oben zeigt die Kaskade der Schritte pro Agent mit Dauer, Modell und Tokens. 12,4 s, 28.038 Tokens und 0,062 €, gegenüber rund 4.300 Tokens und 0,010 € bei den übrigen. Vorfälle CAP-04 und CAP-05.",
  "8703518b": "Auf die Spur von MSG-A-10 klicken: der Vorfall «429 · Wiederholung 1 (2 s)».",
  "f1dbf306": "Filter: Ergebnis → Mit menschlichem Eingreifen (es bleiben MSG-A-04, MSG-A-08 und MSG-A-13). Den Filter entfernen.",
  "9ebe06e9": "Schaltfläche Reasoning anzeigen bei MSG-A-08 (führt zu Schritt 13; mit dem Menü zurückkehren).",
  "7ef09a1e": "Im Bereich Nachvollziehbarkeit können wir jede Meldung Schritt für Schritt verfolgen: welcher Agent was getan hat, wie lange es gedauert hat, mit welchem Modell und was es gekostet hat.",
  "97abe474": "So lässt sich jede Entscheidung aus dem Protokoll rekonstruieren, ob für eine Beschwerde oder für ein Audit.",
  "8254c92a": "Jede Meldung erzeugt eine Spur. Die Kaskade zeigt uns jeden Schritt jedes Agenten mit Dauer, Modell und Eingabe-, Ausgabe- und Reasoning-Tokens.",
  "463b4b10": "Hat die Spur ein Kosten-Cap überschritten, ein Guardrail ausgelöst oder einen Vorfall gehabt, etwa einen Fehler des Anbieters mit Wiederholung, wird das genau hier gekennzeichnet.",
  "c241427f": "Und die Liste lässt sich nach Agent, Kanal, Entscheidung oder Ergebnis filtern.",
  "8ed822af": "Bei einer Beschwerde wird die Entscheidung rekonstruiert, ohne jemanden fragen zu müssen, was passiert ist, und der Versicherer kann nachweisen, wie er entschieden hat.",
  "7b1e363d": "Außerdem erreichen die Ausfälle des KI-Anbieters den Kunden nicht: Das System wiederholt und protokolliert sie, sodass wir mit Daten auf dem Tisch mit dem Anbieter sprechen können.",
  "4580638a": "Autonomie",
  "00be148b": "Menü → Autonomie. Block Kontrolle",
  "01aed175": "Abgestufte Autonomie mit klaren Grenzen.",
  "88cba307": "KPIs: 81 % autonome Entscheidungen (Ziel ≥ 80 %), Override-Quote 2,1 %, Genauigkeit 99,1 % gegenüber dem erwarteten Ergebnis.",
  "2fde0fa9": "Stufen L0 bis L3, von Rot bis Grün: Mehrkanal und Klassifizierung auf L3; Extraktion und Regeln auf L2.",
  "232db493": "Stufenänderungen (Audit) → auf die Zeile «Geschäftsregeln · L3 → L2» klicken: der vollständige Datensatz (4,1 % Override in der Woche, genehmigt von M. Ortega). Mit ‹ › zu «Klassifizierung · L2 → L3» navigieren (99,2 % Genauigkeit bei 4.800 Meldungen).",
  "17ec0e06": "Der Bereich Autonomie zeigt uns, auf welcher Stufe jeder Agent steht, von L0 bis L3, und bewahrt das Audit jeder Stufenänderung.",
  "d2d2ba7b": "Wir wollen, dass die Freiheit jedes Agenten im Verhältnis zum Risiko dessen steht, was er entscheidet, und zu seiner Erfolgsbilanz, und dass nichts ohne Daten, die es stützen, eine Stufe aufsteigt.",
  "d73628c6": "Auf L0 schlägt der Agent nur vor. Auf L1 schlägt er vor und ein Mensch bestätigt jeden Fall. Auf L2 entscheidet er innerhalb der Guardrails und eskaliert alles andere an einen Menschen. Und auf L3 entscheidet und handelt er und wird danach auditiert.",
  "944c1d22": "Jeder Auf- oder Abstieg wird mit Grund, den belegenden Daten und dem Namen dessen protokolliert, der ihn genehmigt hat.",
  "9f845f3b": "Eines der Kriterien ist die Korrekturquote: Korrigieren die Sachbearbeiter mehr als 3 % der Entscheidungen eines Agenten, steigt dieser Agent eine Stufe ab.",
  "05fd4958": "Wir machen es wie bei einem neuen Sachbearbeiter: Wir geben ihm mehr Autonomie, wenn er Urteilsvermögen zeigt, und nehmen sie ihm, wenn er sich irrt.",
  "9b394a40": "In der Demo erreichte der Agent Regeln L3 und fiel auf L2 zurück in der Woche, in der die Korrekturen 4,1 % erreichten. Und hinter jeder Änderung steht jemand, der sie abzeichnet.",
  "7a58cacb": "Guardrails",
  "fe31b272": "Menü → Guardrails. Block Kontrolle",
  "fceae977": "Die Regeln des Versicherers haben immer Vorrang vor dem Modell.",
  "0a65efc7": "KPIs: 11 von 12 aktiv, 454 Auslösungen in 14 Tagen, die am häufigsten ausgelöste (G-02).",
  "ba7a1f3c": "Tabelle G-01 bis G-12. Mit der Maus über die Mini-Balken der Auslösungen pro Tag fahren.",
  "8084f2b5": "Auf G-04 · Verletzte = ja klicken: die Karte mit Beschreibung und letzten Auslösungen. In der Liste der Auslösungen die von MSG-A-08, mit ihrer Spur verknüpft.",
  "b104564e": "Auf G-02 · Betrag klicken: 118 Auslösungen, 62 % der Eskalationen.",
  "d8916fa8": "Schalter G-09 (inaktiv): erklären, warum er aus ist (durchschnittliche Transkriptionskonfidenz 0,91).",
  "5397fea2": "Optional: Neuer Guardrail (Fenster mit dem Formular). Ohne Speichern schließen.",
  "46dbb818": "Der Bereich Guardrails versammelt die Bedingungen, die einen Agenten daran hindern, selbst zu entscheiden, und sagt uns, wie oft jede ausgelöst wurde.",
  "a348ab3d": "So können wir garantieren, dass die Regeln des Versicherers immer Vorrang vor dem haben, was das Modell sagt.",
  "3b2ba53a": "Ein Guardrail ist eine Bedingung, die geprüft wird, bevor eine Entscheidung ausgeführt wird: eine Konfidenz unter der Schwelle, ein Betrag über der Grenze der Sparte, ein Verletzter, eine nicht bestimmbare Sparte oder ein Betrugshinweis.",
  "caf14498": "Löst er aus, wird die Entscheidung nicht ausgeführt: Je nach Fall geht sie an einen Menschen, wechselt auf ein günstigeres Modell oder die Spur wird gekennzeichnet.",
  "e33f208f": "Jeder Guardrail hat seine Karte, seine Auslösungen pro Tag und einen Schalter zum Ein- und Ausschalten.",
  "c352e55b": "Der Guardrail für den Betrag zum Beispiel wurde 118-mal in 14 Tagen ausgelöst und erklärt 62 % der Eskalationen. Will das Geschäft morgen die Grenze für Kfz anheben, weiß es genau, wie viele Fälle betroffen sind.",
  "0f65455c": "Und jeder Guardrail, der ein- oder ausgeschaltet wird, wird in der Historie mit dem Namen dessen protokolliert, der es getan hat.",
  "7141aa10": "Menü → Menschliches Eingreifen. Block Kontrolle",
  "e158bd2d": "Eine Freigabe in 10 Sekunden ist nur eine Unterschrift: Deshalb messen wir, ob die Prüfung echt ist.",
  "c11cd3e7": "KPIs: 3.180 eskaliert (19 %), Override 2,1 %, 2 zur Prüfung ausstehend, Expressprüfungen 3,3 %, wirksame menschliche Aufsicht «Abgedeckt».",
  "6813f95b": "Aufsichtsmechanismen: Eskalation, Override und Stufe, Kill Switch, regulatorische Kontrolle.",
  "1577422d": "Prüfwarteschlange: die drei Spuren des Stapels. Auf MSG-A-04 klicken: die Karte der Spur mit der Prüfung von L. Prieto, der freigibt, und dem Grund. Mit › zu MSG-A-08 und MSG-A-13 navigieren (ausstehend).",
  "fd2454e4": "Eskalationen: der Ring der Ursachen (G-02 62 %, G-04 20 %, G-05 11 %).",
  "deabdb4d": "Qualität der Prüfung: Zeiten nach Intervall, 3,3 % der Freigaben in unter 30 Sekunden und die Tabelle pro Sachbearbeiter mit seiner KI-Schulung.",
  "f5c3cfa0": "Maßnahmen: auf M-10 klicken (Schulung der Sachbearbeiter).",
  "bc491462": "Der Bereich Menschliches Eingreifen zeigt uns die Warteschlange mit allem, was die Agenten eskalieren, wer es prüft, wie lange es dauert und wie viele Entscheidungen am Ende geändert werden.",
  "b3f7934c": "So können wir nachweisen, dass die menschliche Prüfung echt ist und niemand unterschreibt, ohne hinzusehen.",
  "abae6411": "Jede eskalierte Spur kommt in eine Warteschlange mit Grund, Status und der prüfenden Person. Einen eskalierten Fall abzuschließen, ist kein Override.",
  "122b1fd0": "Ein Override liegt vor, wenn ein Sachbearbeiter eine Entscheidung ändert, die der Agent selbst getroffen hat, zum Beispiel eine automatische Freigabe, die zur Prüfung geht, und er wird mit seinem Grund protokolliert.",
  "27ec0166": "Das Panel misst auch, wie geprüft wird: wie lange jeder Sachbearbeiter braucht, welcher Anteil der Freigaben in unter 30 Sekunden unterschrieben wird und welche Sachbearbeiter die KI-Schulung haben.",
  "8129bdb0": "Die Warteschlange belegt, dass ein Mensch die Entscheidung getroffen hat, mit Name und Uhrzeit. In der Demo werden 3,3 % der Freigaben in unter 30 Sekunden unterschrieben, und drei Sachbearbeiter überschreiten das Maximum von 5 %.",
  "7539bc48": "Zwei von ihnen haben die KI-Schulung noch nicht, und das ist bereits eine offene Maßnahme.",
  "556f1edb": "Außerdem fließt jeder Override in die Autonomie ein: Korrigieren die Sachbearbeiter mehr als 3 % dessen, was der Agent selbst entscheidet, schlägt das Panel vor, seine Stufe zu senken, und ein Mensch genehmigt es.",
  "cc1a39a6": "Betrug: MSG-A-13, MSG-A-09 und MSG-A-02",
  "f238e757": "Menü → Betrug. Block Risiko",
  "385533fd": "Der Indikator beschuldigt nicht: Er priorisiert, und die Entscheidung trifft ein Mensch.",
  "a5abe925": "Die drei Stufen: ohne Hinweise (0-39), in Beobachtung (40-69), SIU (≥ 70).",
  "f01157b4": "KPIs: 13 analysiert, 3 mit Hinweisen, 2.080 € zurückgehalten in 3 Zahlungen, 80 an die SIU eskaliert in 14 Tagen, 21 % bestätigt, 76 % Falsch-Positive.",
  "f0a2e18f": "Fälle des Stapels → auf MSG-A-13 klicken: die Fallkarte. Aufschlüsselung des Scores nach Indikator (Police von 21 Tagen, vage Schilderung, keine Anzeige und keine Einbruchsspuren, Eile, 5.000 € Schmuck ohne Rechnung), die Meldung mit den markierten Zitaten und die Nachverfolgung.",
  "01e5e005": "Mit › zu MSG-A-09 navigieren: das geteilte Konto. Und zu MSG-A-04: der Gegenindiz (Pablo ist angegeben), das den Score auf 30 senkt.",
  "3022d2f7": "Betrugsszenarien EF-01 bis EF-08: EF-02 öffnen.",
  "bb88e569": "Beziehungskarte: MSG-A-09 und MSG-A-02 über dasselbe Konto verbunden, mit einer Akte vom August eines anderen Kontoinhabers.",
  "4750f1d9": "Indikatorkatalog → Neuer Indikator: Die Vorschau zeigt, welche Meldungen des Stapels ihn auslösen würden. Ohne Speichern schließen.",
  "402bd36e": "Fairness nach Kanal: WhatsApp erhält wegen seines Tons 1,8-mal mehr Warnungen (Maßnahme M-18).",
  "cd367284": "Wir wollen die zweifelhafte Zahlung stoppen, ohne den Kunden zu blockieren, der nichts falsch gemacht hat.",
  "b08255f2": "Um diese Muster zu erkennen, kombiniert die Plattform drei Quellen: was die KI aus der Schilderung des Kunden versteht, mit wörtlichen Zitaten aus der Meldung; die Historie von Policen, Schäden und Dienstleistern; und deterministische Regeln.",
  "2e9dff8f": "Damit erhält jede Meldung einen Score von 0 bis 100. Unter 40 wird er nur protokolliert. Zwischen 40 und 69 wird bearbeitet, aber die Zahlung bis zur Prüfung zurückgehalten. Und ab 70 geht der Fall an die SIU.",
  "2c39799c": "Die Historie kann auch abziehen: Widerspricht eine Angabe dem Hinweis, senkt dieses Gegenindiz den Score. Jeder Fall hat seine Karte mit der Aufschlüsselung nach Indikator, der Karte der Beziehungen zu anderen Schäden und der Nachverfolgung.",
  "d720c836": "Kein Schaden wird automatisch abgelehnt, und der Kunde sieht den Hinweis nie; erwähnt ihn ein an ihn gerichteter Text, blockiert ihn ein Guardrail. Riskante Fälle erreichen die SIU mit bereits vorbereiteter Karte.",
  "a7a22ab4": "In der Demo sind 2.080 € zurückgehalten, und ein Cap überwacht dieses Geld, um rechtmäßigen Kunden nicht zu schaden. Und die 76 % Falsch-Positive erinnern uns daran, warum ein Indikator allein nie entscheidet.",
  "ba1a8c64": "Reasoning und Replay",
  "66c0b2d4": "Menü → Reasoning und Replay. Block Qualität",
  "21b0da3c": "Wir auditieren, was passiert ist, und testen, bevor wir etwas ändern.",
  "be0f508e": "In der Liste auf MSG-A-08 klicken. Rechts die Kette der Agenten und die Meldung mit den Zitaten, die jeder Agent genutzt hat, in der Farbe des jeweiligen Agenten.",
  "3f191ff7": "Pro Agent: Konfidenz nach Sparte (Kfz gegenüber Gesundheit), Herkunft jedes extrahierten Felds (wörtlich, normalisiert, abgeleitet oder null), Regelmatrix mit dem Weg zur Entscheidung und die Tokens gegenüber CAP-05.",
  "3b67775a": "Den mittleren Trenner ziehen, um das Reasoning zu verbreitern.",
  "5891d44e": "Replay → Modus Identisch → ausführen: gleiche Entscheidung.",
  "ca7deaef": "Modus What-if → Modell von Regeln: gpt-5-mini → ausführen: der Unterschied in Sparte, Entscheidung, Kosten und Latenz.",
  "c4643918": "Replay-Verlauf: RP-0006 (MSG-A-04 mit gpt-5-mini: gleiche Entscheidung, −82 % Kosten) und RP-0005 (gpt-5-nano machte aus einem Freigegeben ein Zu prüfen).",
  "466fa18d": "Der Bereich Reasoning und Replay zeigt uns, wie jeder Agent zu seinem Ergebnis kam, und lässt uns eine echte Spur mit einem anderen Modell oder einer anderen Prompt-Version wiederholen.",
  "06e29879": "So können wir jede Änderung mit echten Fällen testen, bevor sie den Kunden erreicht.",
  "63ab9e50": "Das Reasoning wird Agent für Agent gezeigt: was er erhalten hat, welche Sätze der Meldung er als Beleg genutzt hat und was er geliefert hat.",
  "43da7f03": "Wichtig: Das ist nicht die interne Gedankenkette des Modells, sondern der strukturierte Datensatz, den jeder Agent mit seinen Zitaten zurückgibt.",
  "dbff3819": "Das Replay wiederholt eine echte Spur auf zwei Arten. Im Modus Identisch prüft es, dass sich das Ergebnis reproduzieren lässt.",
  "3d2bc355": "Im Modus What-if ändert es das Modell oder die Prompt-Version und zeigt uns den Unterschied in Entscheidung, Kosten und Latenz.",
  "302b97ff": "Jeder Modellwechsel wird mit echten Fällen getestet, bevor er in Produktion geht.",
  "ba4940ab": "In der Demo behielt der Wechsel des Agenten Regeln auf gpt-5-mini die Entscheidung bei 82 % weniger Kosten; gpt-5-nano dagegen machte aus einer Freigabe ein Zu prüfen. Das Replay erkennt es, bevor der Kunde es merkt.",
  "d1c7acbc": "Und wenn der Auditor kommt und fragt, warum eine Entscheidung getroffen wurde, steht die Antwort hier.",
  "58b572bd": "Knowledge Bases",
  "0aee31f1": "Menü → Knowledge Bases. Block Qualität",
  "c926e085": "Auch Wissen verschlechtert sich, und wir überwachen es genau wie die Agenten.",
  "878b0e74": "KPIs: 9 Datenbanken (1 echt, 8 simuliert), 5 gesund, durchschnittlicher Recall 0,86, 3,27 % der Anfragen ohne Antwort, 6 Rubriken mit einer Übereinstimmung Judge–Mensch von 0,93.",
  "54fb51e3": "Auf KB-02 · Kfz-Bedingungen 2026 (beeinträchtigt) klicken: Reiter Zustand, jede Metrik gegenüber ihrer Schwelle; der Recall sinkt um 6 Punkte.",
  "1d37c3f8": "Reiter Quelle und Synchronisierung: die 340 Dokumente der Bedingungen 2024, die über einen schlecht gefilterten Ordner hereinkamen.",
  "39b1285b": "Reiter Vergleich: vier Konfigurationen, bewertet mit der Rubrik R-02; mit Gültigkeitsfilter steigt der Recall von 0,81 auf 0,88. Anwenden.",
  "1d26c976": "Reiter Versionen: «Zu dieser Version zurückkehren».",
  "c08966e5": "Mit › zu KB-06 · Werkstattnetzwerk (kritisch) navigieren: Die API antwortet mit 401, und 14 ausgeschiedene Werkstätten stehen noch als Vertragswerkstätten da.",
  "d7ab484e": "Rubriken → eine bearbeiten: Die Gewichte müssen 100 ergeben, und es wird eine neue Version gespeichert. Ohne Speichern schließen.",
  "ef502a93": "Im Bereich Knowledge Bases messen wir den Zustand des Wissens, das die Agenten abfragen: die Versicherungsbedingungen, das Handbuch der Schadenbearbeitung, das Netzwerk der Gesundheitsdienstleister oder das Werkstattnetzwerk.",
  "d5f3592a": "Das ist wichtig, denn so gut das Modell auch ist: Fragt es ein veraltetes Dokument ab, entscheidet es schlecht.",
  "27485d88": "Jede Wissensdatenbank wird laufend anhand einer Rubrik bewertet, mit Metriken wie dem Recall oder den unbeantworteten Anfragen, und jede Metrik hat ihre Schwelle.",
  "f730d3aa": "Die Karte zeigt uns ihre Konfiguration, woraus sie gespeist wird und wie oft sie synchronisiert wird, ihre Versionen und einen Vergleich, der verschiedene Konfigurationen desselben Inhalts bewertet, um vor dem Anwenden die beste zu wählen.",
  "7e2d27d3": "Mit alten Bedingungen kann der Agent einen Selbstbehalt oder einen Ausschluss anwenden, den es nicht mehr gibt.",
  "f486c45f": "In der Demo hat die Datenbank der Kfz-Bedingungen 6 Punkte Recall verloren, weil 340 Dokumente von 2024 hineingerutscht sind, und ein Gültigkeitsfilter hebt ihn von 0,81 auf 0,88.",
  "b99c6e5f": "Außerdem wird die Änderung gemessen, bevor sie veröffentlicht wird: Die Neuindexierung geht nur in Produktion, wenn sich die Rubrik nicht verschlechtert.",
  "8996a5e0": "Compliance: das Thermometer",
  "b2c97ef0": "Menü → Compliance. Block Compliance und Kosten",
  "e98062b8": "Die Lösung versetzt den Versicherer in die Lage, nachzuweisen, dass er die Vorschriften einhält.",
  "8fb565ec": "Kopfbereich: Abdeckung 87 %, 26 Kontrollen abgedeckt und 9 teilweise, 14 in den Spuren gemessen und 21 erklärt.",
  "d748680e": "Die vier Thermometer: AI Act 86 %, RGPD 87 %, DORA 100 %, EIOPA und Solvencia II 80 %. Auf eines klicken, um die Matrix zu filtern.",
  "276de081": "Matrix Vorschrift → Kontrolle: Filter Nur teilweise. Auf die DSFA (RGPD art. 35) und den KI-Hinweis in WhatsApp (AI Act art. 50) hinweisen.",
  "44c9e218": "Lebenszyklus einer Spur: die acht Schritte mit ihrer Vorschrift und ihrer Frist.",
  "4eb9e9d8": "Inventar personenbezogener Daten → auf MSG-A-12 klicken: der Text mit den markierten Daten und sein Block _gobernanza.",
  "ecb3f156": "Compliance-Nachweise exportieren (optional).",
  "a1813c2e": "Der Bereich Compliance gibt uns ein regulatorisches Thermometer, mit dem wir verstehen, auf welchem Stand der Einhaltung wir beim AI Act, der DSGVO, DORA, EIOPA und Solvency II sind, und es wird aus allen Spuren berechnet, die das System erzeugt.",
  "80b17cb7": "Es sagt uns, wie viel wir heute nachweisen können und was uns fehlt.",
  "860a218a": "Die Kontrollen sind nach Vorschrift gruppiert. Einige werden direkt in den Spuren gemessen, etwa dass jede Entscheidung ihren vollständigen Datensatz hat. Andere werden mit ihrem dokumentarischen Nachweis erklärt, etwa der Exit-Plan eines Anbieters.",
  "d60b5984": "Eine Matrix sagt uns Artikel für Artikel, was die Vorschrift verlangt, wie die Lösung es umsetzt und welche Spuren es belegen.",
  "eef6f6e0": "Wir haben auch das Inventar der personenbezogenen Daten jeder Meldung und die Integritätskette des Protokolls: Ändert jemand eine bereits versiegelte Spur, bricht die Kette ab diesem Punkt und das Thermometer wird rot.",
  "6911bd92": "Die Abdeckung sagt uns, wie viel wir heute nachweisen können; in der Demo 87 %. Die gelben Kontrollen sind die Aufgabenliste, und sie sind echt, etwa die ausstehende Folgenabschätzung oder der fehlende KI-Hinweis in WhatsApp.",
  "2b1ac769": "Das Panel beschönigt nichts.",
  "ed1b1937": "Ein manipulierter Datensatz wird sofort erkannt, und deshalb kann ein Auditor der Historie vertrauen. Es ist kein Zertifikat, aber es ist der Nachweis, den der DSB braucht, mit jeder Spur neu berechnet.",
  "2ccbd05a": "FinOps",
  "315d7c47": "Menü → FinOps. Block Compliance und Kosten",
  "58517c5f": "Wir wollen nicht das günstigste Modell, sondern das günstigste Modell, das uns die höchste Qualität liefert.",
  "fc178e03": "KPIs: Kosten heute 17,33 € (87 % des Tages-Caps von 20 €), Monatskosten 296,40 € von 500 € mit einer Prognose von 428 €, 3 Caps überschritten, 0,0128 € pro Meldung. Auf Monatskosten klicken: das Fenster mit dem Detail.",
  "eea8000e": "Wie sich die Ausgaben jedes Agenten entwickeln: die Zeile Regeln in Rot (13,70 € / 12 €, 80 % des Gesamtbetrags).",
  "09a171b6": "Kostenwarnungen: CAP-03 (was es selbst getan hat: Herabstufung auf gpt-5-mini bis 00:00) und CAP-04/CAP-05 bei MSG-A-08.",
  "593544a6": "Modelle: Preis, Aufrufe, Tokens, Kosten, p95 und Qualität (gültiges JSON, ohne Wiederholung, stabil im Replay, Genauigkeit). Auf eine Legende eines Diagramms klicken, um eine Reihe auszublenden.",
  "363f5f62": "Empfehlungen: R-01 bis R-04.",
  "69388af0": "Im Bereich FinOps steuern wir die Ausgaben sekundengenau und über Aktionen.",
  "f73ba5ba": "Die Anbieter von KI-Diensten für Unternehmen sagen uns alle 8 Stunden, wie viel wir ausgegeben haben, und in dieser Zeit kann viel passieren: Wir können morgens mit Ausgaben aufwachen, die wir nicht wollten.",
  "260d3079": "Hier sehen wir live, wie viel wir pro Agent, pro Modell und pro Token-Art ausgeben, und die Caps handeln selbst, sobald sie überschritten werden.",
  "c823e08b": "Jede Entscheidung addiert ihre Kosten in dem Moment, in dem sie entsteht, denn die Spur erfasst die Tokens jedes Agenten und die Plattform multipliziert sie mit dem Preis seines Modells.",
  "8b2d4290": "Die Caps wirken auf diese Kosten: pro Agent, global, pro Meldung und für Reasoning-Tokens. Jedes Cap hat eine verknüpfte Aktion.",
  "9e6b8cf9": "Wird eines überschritten, erklärt die Warnung, was passiert ist, was das System automatisch getan hat, zum Beispiel bis Mitternacht auf ein günstigeres Modell zu wechseln, ohne den Dienst anzuhalten, und welche Aktion es vorschlägt.",
  "65bc4628": "Die Ausgaben werden nach Token-Art aufgeschlüsselt, um zu verstehen, woher sie kommen. Und eine Tabelle kreuzt Kosten und Qualität jedes Modells: was es kostet und wie oft es eine gültige Antwort liefert, ohne Wiederholungen und stabil im Replay.",
  "33146d2d": "Wir warten keine 8 Stunden, bis der Anbieter uns sagt, was passiert ist: Das Cap greift bei derselben Meldung, die es überschreitet. In der Demo hat der Agent Regeln sein Cap überschritten, und das System hat selbst das Modell gewechselt, ohne den Dienst anzuhalten.",
  "6638afc9": "Die Ausgaben des Monats liegen bei 296 € von 500 €, mit einer Prognose von 428 €, und es gibt keine Überraschungen auf der Rechnung.",
  "6ac9754e": "Und wir wissen genau, wo wir ansetzen müssen: Der Agent Regeln verursacht 80 % der Ausgaben, und darin wiegt am meisten der Text, den gpt-5 erzeugt. Die Empfehlungen sagen uns, wie viel jeder Hebel spart.",
  "968f41cd": "Korrekturmaßnahmen",
  "17e3a888": "Menü → Korrekturmaßnahmen. Block Verbesserung und Audit",
  "f41cc18b": "Kosten unter Kontrolle und jedes Problem mit seinem Verantwortlichen.",
  "6a200077": "Filter: Kosten und Quick Wins. Entfernen.",
  "6c73541b": "Karte M-01 · Regeln überschreitet sein Tages-Cap: drei Alternativen, die empfohlene «gpt-5-mini für die direkte Freigabe verwenden» (−237 €/Monat, validiert mit dem Replay RP-0006). Auf die Karte klicken: die Karte mit den Alternativen nebeneinander.",
  "af7d5980": "Simulieren → Anwenden: Die erzielte Ersparnis steigt auf 237 €/Monat.",
  "06ce7802": "M-02 · Kosten und Reasoning bei MSG-A-08 → Genehmigung anfordern: Sie bleibt «Ausstehend beim KI-Ausschuss» (41 € ausstehend).",
  "7f50aa51": "Rückgängig bei M-01: Die Ersparnis geht auf null zurück. Erneut anwenden.",
  "cd324aae": "Auf den Kreis des Thermometers klicken (führt zu Compliance) oder auf M-10 (Schulung der Sachbearbeiter).",
  "7b2d7940": "Der Bereich Korrekturmaßnahmen versammelt in einer einzigen Liste die Probleme, die der Rest des Panels erkennt, jedes mit seinen Alternativen, seiner Ersparnis und wer sie genehmigen muss.",
  "8693cfac": "Wir wollen, dass jedes Problem einen Verantwortlichen, eine Alternative und eine Prüfung hat.",
  "f38ef7a2": "Die Liste umfasst Kosten, Wissen, Compliance, Qualität und Resilienz.",
  "1b010ab3": "Jedes Problem kommt aus einem anderen Bereich des Panels und bringt mehrere Alternativen mit, die empfohlene markiert: ihre Wirkung, ihre Nebenwirkung, der Aufwand, wer sie genehmigt und wie sie vor dem Anwenden validiert wird.",
  "392ac3b8": "Von hier aus können wir eine Alternative simulieren, anwenden oder ihre Genehmigung anfordern und sie bei Bedarf rückgängig machen. Wird eine Maßnahme verifiziert, aktualisiert sich das Compliance-Thermometer von selbst.",
  "c2ce73b8": "Jede Ersparnis ist belegt. In der Demo wird die Maßnahme, die die einfachen Fälle auf gpt-5-mini verlegt, mit einem Replay validiert, das keine Entscheidung geändert hat, und beim Anwenden steigt die erzielte Ersparnis um 237 € im Monat.",
  "8ee4a581": "Was eine Genehmigung braucht, wartet auf den KI-Ausschuss, und alles wird protokolliert.",
  "4a1474dd": "Historie",
  "1563bbd4": "Menü → Historie. Block Verbesserung und Audit",
  "00e3278f": "Das ist das Logbuch, das die Aufsicht verlangt, und es füllt sich von selbst.",
  "b565ab7c": "Die Zeitleiste: oben, was in der Demo mit dem Nutzer «Operator (diese Sitzung)» getan wurde: der Kill Switch von Extraktion, M-01 angewandt und rückgängig gemacht, M-02 ausstehend, die auf KB-02 angewandte Konfiguration.",
  "de311403": "Typ-Chips: Betrieb, Richtlinien, Overrides (die von J. Herrera und S. Gil am 15/09, dem Tag, an dem Regeln eine Stufe abstieg), Prüfungen (die von L. Prieto zu MSG-A-04), Deployments (Wechsel von Modell und Prompt), Vorfälle (die Häufung von 429-Fehlern).",
  "9f2c69f2": "Die Historie ist die Zeitleiste von allem, was sich im System geändert hat, mit Urheber und Uhrzeit. Sie dient jedem Auditor als Logbuch, und niemand muss sie von Hand führen.",
  "aa5a24fc": "Sie protokolliert jede Aktion mit Nutzer und Uhrzeit: angehaltene Agenten, ein- oder ausgeschaltete Guardrails, angewandte oder rückgängig gemachte Maßnahmen, Prüfungen, Overrides, Wechsel von Modell, Prompt und Stufe sowie Vorfälle.",
  "24403b6b": "Er lässt sich nach Ereignistyp filtern.",
  "4bf6eb0a": "Ein Auditor sieht jede Änderung mit Urheber und Datum, und niemand muss aus E-Mails rekonstruieren, was passiert ist. Alles, was wir in dieser Demo angefasst haben, steht schon hier.",
  "336a6807": "Abschluss",
  "e33d01df": "Governance-Panel → Historie",
  "51b69ece": "Was KI in Produktion bringt und dort hält, ist die Governance.",
  "fbdfe9a1": "Wir haben 13 Meldungen über fünf verschiedene Kanäle hereinkommen sehen. 10 wurden selbstständig freigegeben und 3 gingen an einen Menschen, jede mit ihrem Grund und dem Satz des Kunden, der ihn belegt.",
  "07aebb31": "Wir haben auch einen Fall gesehen, der an die SIU geht, und drei zurückgehaltene Zahlungen, ohne jemanden zu blockieren.",
  "8a233348": "Und um all das herum die Governance: Agenten mit ihrer Autonomiestufe, ihren Berechtigungen und ihrem Verantwortlichen; Guardrails, mit denen die Regeln des Versicherers Vorrang vor dem Modell haben; ein Budget, das jeden Tag gesteuert wird; und eine Spur für jede Entscheidung, mit der wir nachweisen können, wie entschieden wurde.",
  "1b491b87": "KI zur Zuordnung von Meldungen ist bereits in Ihrer Reichweite. Was sie in Produktion bringt und dort hält, ist das hier.",
  "d4be097d": "Und es ist keine Idee auf dem Papier: Es ist das, was Logicalis bei Kunden aus verschiedenen Branchen umsetzt, angepasst an die Prozesse, Regeln und Vorschriften jedes einzelnen.",
});
